    translation: '孔子说：“学了知识后按时温习它，不也是很愉快吗？有志同道合的人从远方来，不也是很快乐吗？别人不了解我，我却不恼怒，不也是有才德的人吗？”\n曾子说：“我每天多次进行自我检查：替别人办事是不是尽心竭力呢？同朋友交往是不是诚实守信呢？老师传授的知识是不是复习了呢？”\n孔子说：“我十五岁立志于学习，三十岁能有所成就，四十岁不再迷惑，五十岁懂得了什么是天命，六十岁能听得进不同的意见，七十岁能顺从自己的意愿，又不越出法度。”\n孔子说：“温习学过的知识，可以得到新的理解和体会，就可以凭借这一点做老师了。”\n孔子说：“只学习却不思考，就会迷惑；只空想却不学习，就会疑惑。”\n孔子说：“颜回多么有才德啊！一竹筐饭，一瓢水，住在简陋的小巷子里，别人都受不了那穷困的忧愁，颜回却不改变他自有的快乐。颜回多么有才德啊！”\n孔子说：“懂得学问和事业的人不如喜爱它的人，喜爱它的人不如以它为快乐的人。”\n孔子说：“吃粗粮，喝冷水，弯着胳膊当枕头，乐趣也就在这中间了。用不正当的手段得来的富贵，对于我来说就像天上的浮云一样。”\n孔子说：“几个人一同走路，其中必定有可以做我老师的人。选取他们的优点来学习，看到他们的缺点就对照自己加以改正。”\n孔子在河边感叹说：“消逝的时光就像这河水一样，日夜不停。”\n孔子说：“军队可以改变主帅，普通人的志向却不能改变。”\n子夏说：“广泛地学习并且志向坚定，恳切地发问求教，多思考当前的事情，仁德就在其中了。”',
    theme: '本文是《论语》十二章语录的选编，内容围绕学习与修身展开：既有「学而时习」「温故知新」「学思结合」的学习方法，又有以学为乐、安贫乐道的学习态度，更有「三省吾身」「匹夫不可夺志」「博学而笃志」的修身立志之道，最终归结于一个「仁」字，体现孔子及其弟子为学与做人相统一的追求。写作上属典型的语录体：每章独立成章，短小精悍，多以「子曰」「曾子曰」「子夏曰」领起，用格言式警句直陈观点；善用反问（「不亦……乎」）、比较（「……不如……」）、对偶排比增强语势与节奏；「贤哉，回也」的重复与主谓倒装尤见情感浓度；说理常借比喻，如「逝者如斯夫」「于我如浮云」，言简意丰，含蓄隽永，是先秦说理散文的萌芽，也是中考默写与实词虚词考查的高频语料。',
