        answer: '年与时驰/意与日去/遂成枯落/多不接世/悲守穷庐/将复何及',
        explanation: '这段文字以整齐的四字句为主：「年与时驰」与「意与日去」两两相对，「遂成枯落」与「多不接世」语意相承，「悲守穷庐」与「将复何及」一气贯下，据此在每四个字之后断开即可。断句要依据句意与句式（对偶、排比）双重判断，不能只凭朗读语感。易错点：把「年与时驰」拆成「年／与时驰」，或把「多不接世」与「悲守穷庐」连读，破坏了原文整齐的句式与逐层推进的语意。',
