    translation: '宋国有个姓丁的人家，家里没有井，要出门去打水浇田，所以经常要有一个人住在外面。等到他家挖了井，（丁氏）告诉别人说：“我挖井得到了一个人。”\n有人听说了这件事，就把它传扬开去：“丁氏挖井挖到了一个人。”国都里的人都在谈论这件事，（这件事）传到了宋国国君的耳朵里。宋国国君派人向丁氏询问这件事。丁氏回答说：“（我是说）得到了一个人的劳力，并不是在井里挖到了一个人。”像这样听信传闻，不如没有听到。',
    theme: '本文是一则寓言，写丁氏挖井后省下一个劳力的平常事，被传成挖井挖出一个人的离奇消息，直到宋君派人查问才真相大白，讽刺了传闻失真、以讹传讹的现象，告诫人们对传言要考察、验证，不可轻信盲从，更不可随意传播未经证实的消息，末句「求闻之若此，不若无闻也」直接点明题旨。写作上善于在极短的篇幅里制造误会与反差：「得一人」一语多义，说者指得到一个人的劳力，听者却理解为从井里挖出一个人，误会由此层层放大，从一人之言到「国人道之」，再到惊动国君，传闻如滚雪球般越滚越大，情节简练而波澜起伏；语言质朴洗练，多用短句和对话推进，丁氏的辩解看似平淡，却使讹传不攻自破；最后以议论收束，叙议结合，寓理于事。',
