          { word: '夕日欲颓', explain: '「颓」古义是「坠落」，指夕阳快要落山；今义是「颓废、衰败」。' },
          { word: '四时俱备', explain: '「备」古义是「具备、齐备」，指四季之景都有；今义是「准备、防备」。' }
