          { word: '猿鸟乱鸣', explain: '「乱」形容词用作状语，意为「纷乱地、此起彼伏地」，修饰动词「鸣」。' },
          { word: '未复有能与其奇者', explain: '「奇」形容词用作名词，指奇丽的景色。' }
