    translation: '舜从田地耕作之中被起用，傅说从筑墙的劳作之中被举用，胶鬲从贩卖鱼盐之中被举用，管夷吾从狱官手中被释放并举用，孙叔敖从海滨隐居之地被举用，百里奚从市井之中被赎出并举用。所以上天将要把重大的使命交给这个人的时候，必定先使他的内心痛苦，使他的筋骨劳累，使他经受饥饿之苦，使他身受贫困之苦，使他做事不顺，用这些来使他的心受到震撼，使他的性格坚忍起来，增加他所不具备的才能。\n一个人常常犯错误，然后才能改正；内心忧困，思虑堵塞，然后才能奋起；显露在脸色上，流露在言谈中，然后才能被人了解。一个国家，如果在国内没有守法度的大臣和辅佐君王的贤士，在国外没有势力、地位相当的国家和外来的祸患，这个国家就常常会灭亡。这样以后才知道，忧患使人生存发展，安逸享乐使人萎靡死亡。',
