          '第二段写潭中鱼「佁然不动，俶尔远逝，往来翕忽」，只写鱼而不写水，实际是从侧面表现潭水的清澈。',
          '第四段写「四面竹树环合，寂寥无人」，说明小石潭地处荒僻，作者因此感到恐惧，于是急忙离开了小石潭。',
