        answer: 'D',
        explanation: '本文正是典型的托物寓意之作：全文没有一句直接议论人事，而是通篇说马，借千里马与食马者的关系寄寓人才与统治者的关系，以比喻和象征贯穿始终。D项说「通篇正面说理」「没有运用比喻和象征」，与文本写法完全相反。要注意这类题往往把「借物言志」误判为「直抒胸臆」。',
