        explanation: '「绝」在这里是动词，意为消失、断绝，指大雪封湖之后人和鸟的声音都没有了。「俱」是「都」，修饰「绝」。易错点是照今义解为「绝对」「断绝关系」，或误解为「隔绝」，其实句中说的是声音完全消失，从听觉上写出雪后湖上的静寂与奇寒。',
        difficulty: 1,
