          answer: 'C',
          explanation: 'A项对应第1段分析形势、为建议作铺垫，B项对应第2段「陟罚臧否，不宜异同」，D项对应第4段自述身世与追随先帝的经历，均正确。C项张冠李戴：郭攸之、费祎、董允是「此皆良实，志虑忠纯」的文臣，作者推荐他们掌管宫中之事；只有向宠是「晓畅军事」的将领，分管营中之事。答这类题要把人物与所任之事一一对应，警惕笼统概括。',
          difficulty: 1,
