          type: 'choice',
          stem: '对本文写法与主旨的分析，不正确的一项是（　）',
          options: [
            '全文以议论为主，兼用叙事与抒情，把治国建议、个人身世与君臣之情融为一体。',
            '作者提出广开言路、赏罚严明、亲贤远佞三条建议，其中亲贤远佞是核心，是前两条得以施行的保障。',
            '反复称引「先帝」，既是借先帝之威来劝谏后主，也流露出对知遇之恩的感激与兴复汉室的决心。',
            '结尾「今当远离，临表涕零，不知所言」表明作者对北伐没有把握，已经对出兵产生了动摇。',
          ],
          answer: 'D',
          explanation: '本文前五段以议论提出三条建议，中间两段以叙事追忆身世、表明忠心，叙事之中饱含抒情，A项正确；三条建议里「亲贤远佞」是核心，因为只有任贤去佞，广开言路、赏罚严明才有保障，文中举先汉、后汉之例正是为此，B项正确；文中十三次称引「先帝」，兼有劝谏与感恩之用，C项正确。D项误读情感：「临表涕零，不知所言」是临别之际情不能已的真诚流露，表现的是对先帝、对蜀汉的拳拳之心，并非对战事失去把握、动摇不定。',
          difficulty: 3,
